11	/* !
12	 * \file histogram.asc
13	 * \brief
14	 */
15	
16	#include <cstdint>
17	#include <vector>
18	#include <algorithm>
19	
20	#include <iostream>
21	
22	#include "acl/acl.h"
23	
24	#include "c_api/asc_simd.h"
25	#include "utils/std/cmath.h"
26	#include "data_utils.h"
27	
28	constexpr uint32_t TOTAL_LENGTH = 256;
29	constexpr uint32_t NUM_BLOCKS = 1;
30	constexpr uint32_t BLK_NUM = 1;
31	
32	__simd_vf__ inline void histogram_vf(
33	    __ubuf__ uint8_t* x_local, __ubuf__ uint16_t* y_local, uint32_t data_len, uint16_t one_rep_size,
34	    uint16_t repeat_time)
35	{
36	    vector_bool vmask_u8 = asc_create_mask_b8(PAT_ALL);
37	    vector_bool vmask_u16 = asc_create_mask_b16(PAT_ALL);
38	    vector_uint8_t src_reg;
39	    vector_uint16_t dst0_reg;
40	    vector_uint16_t dst1_reg;
41	
42	    asc_duplicate_scalar(dst0_reg, 0);
43	    asc_duplicate_scalar(dst1_reg, 0);
44	    for (uint16_t i = 0; i < repeat_time; ++i) {
45	        asc_loadalign(src_reg, x_local + i * one_rep_size);
46	        asc_frequency_histogram_bin0(dst0_reg, src_reg, vmask_u8);
47	        asc_frequency_histogram_bin1(dst1_reg, src_reg, vmask_u8);
48	    }
49	
50	    asc_storealign(y_local, dst0_reg, vmask_u16);
51	    asc_storealign(y_local + 128, dst1_reg, vmask_u16);
52	}
53	
54	__vector__ __global__ void histogram_custom(__gm__ uint8_t* x, __gm__ uint16_t* y)
55	{
56	    asc_init();
57	
58	    constexpr uint32_t block_length = TOTAL_LENGTH / NUM_BLOCKS;
59	
60	    __gm__ uint8_t* x_gm = x + block_idx * block_length;
61	    __gm__ uint16_t* y_gm = y;
62	
63	    __ubuf__ uint8_t x_local[block_length];
64	    __ubuf__ uint16_t y_local[256];
65	
66	    uint32_t burst_length = block_length * 1;
67	    uint32_t out_burst_length = 256 * 2;
68	    uint64_t src_stride = 0;
69	    uint32_t dst_stride = 0;
70	
71	    asc_copy_gm2ub_align((__ubuf__ uint8_t*)x_local, x_gm, burst_length);
72	    asc_sync_notify(PIPE_MTE2, PIPE_V, EVENT_ID0);
73	    asc_sync_wait(PIPE_MTE2, PIPE_V, EVENT_ID0);
74	
75	    uint16_t one_rep_size = asc_get_vf_len() / sizeof(uint8_t);
76	    uint16_t repeat_time = AscendC::Std::ceil_div(block_length, one_rep_size);
77	    histogram_vf((__ubuf__ uint8_t*)x_local, (__ubuf__ uint16_t*)y_local, block_length, one_rep_size, repeat_time);
78	    asc_sync_notify(PIPE_V, PIPE_MTE3, EVENT_ID0);
79	    asc_sync_wait(PIPE_V, PIPE_MTE3, EVENT_ID0);
80	
81	    asc_copy_ub2gm_align(
82	        y_gm, (__ubuf__ uint16_t*)y_local, BLK_NUM, out_burst_length, asc_store_l2_cache_mode::NORMAL_FIRST_VICTIM,
83	        src_stride, dst_stride);
84	    asc_sync();
85	}
86	
87	std::vector<uint16_t> kernel_histogram(std::vector<uint8_t>& x)
88	{
89	    constexpr uint32_t num_blocks = NUM_BLOCKS;
90	    uint32_t total_length = x.size();
91	    size_t x_byte_size = total_length * sizeof(uint8_t);
92	    size_t y_byte_size = 256 * sizeof(uint16_t);
93	    int32_t device_id = 0;
94	    uint8_t* x_host = x.data();
95	    uint8_t* y_host = nullptr;
96	    uint8_t* x_device = nullptr;
97	    uint16_t* y_device = nullptr;
98	
99	    aclInit(nullptr);
100	    aclrtSetDevice(device_id);
101	
102	    aclrtMallocHost((void**)(&y_host), y_byte_size);
103	    aclrtMalloc((void**)&x_device, x_byte_size, ACL_MEM_MALLOC_HUGE_FIRST);
104	    aclrtMalloc((void**)&y_device, y_byte_size, ACL_MEM_MALLOC_HUGE_FIRST);
105	
106	    aclrtMemcpy((uint8_t*)x_device, x_byte_size, x_host, x_byte_size, ACL_MEMCPY_HOST_TO_DEVICE);
107	
108	    histogram_custom<<<num_blocks, 0>>>(x_device, y_device);
109	    aclrtSynchronizeDevice();
110	
111	    aclrtMemcpy(y_host, y_byte_size, (uint8_t*)y_device, y_byte_size, ACL_MEMCPY_DEVICE_TO_HOST);
112	    std::vector<uint16_t> y((uint16_t*)y_host, (uint16_t*)(y_host + y_byte_size));
113	
114	    aclrtFree(x_device);
115	    aclrtFree(y_device);
116	    aclrtFreeHost(y_host);
117	
118	    aclrtResetDevice(device_id);
119	    aclFinalize();
120	
121	    return y;
122	}
123	
124	uint32_t verify_result(std::vector<uint16_t>& output, std::vector<uint16_t>& golden)
125	{
126	    if (std::equal(golden.begin(), golden.end(), output.begin())) {
127	        std::cout << "test pass!" << std::endl;
128	        return 0;
129	    } else {
130	        std::cout << "test fail!" << std::endl;
131	        return 1;
132	    }
133	}
134	
135	int32_t main(int32_t argc, char* argv[])
136	{
137	    constexpr uint32_t total_length = TOTAL_LENGTH;
138	    std::vector<uint8_t> x(total_length);
139	    std::vector<uint16_t> golden(256);
140	
141	    size_t x_file_size = 0;
142	    size_t golden_file_size = 0;
143	    if (!ReadFile("./input/input_x.bin", x_file_size, x.data(), total_length * sizeof(uint8_t))) {
144	        std::cout << "[Failed] Failed to read input data file!" << std::endl;
145	        return 1;
146	    }
147	    if (!ReadFile("./output/golden.bin", golden_file_size, golden.data(), 256 * sizeof(uint16_t))) {
148	        std::cout << "[Failed] Failed to read golden data file!" << std::endl;
149	        return 1;
150	    }
151	
152	    std::vector<uint16_t> output = kernel_histogram(x);
153	    return verify_result(output, golden);
154	}
