// AscendC Histc kernel — multi-core element-by-element histogram
// bin_idx = trunc((val - min) / bin_width), elements outside [min,max] excluded

#include "kernel_operator.h"

constexpr int32_t TILE_SIZE = 256;

template <typename T>
class KernelHistc {
public:
    __aicore__ inline KernelHistc() {}
    __aicore__ inline void Init(
        __gm__ T *xGm,
        __gm__ int32_t *outputGm,
        uint32_t numel,
        uint32_t bins,
        uint32_t chunkSize,
        uint32_t maxNumTiles,
        float invBw,
        float minVal);
    __aicore__ inline void Process();

private:
    AscendC::GlobalTensor<T> xGm_;
    AscendC::GlobalTensor<int32_t> outputGm_;
    AscendC::TPipe pipe_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> histBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tileBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> castBuf_;
    uint32_t numel_;
    uint32_t bins_;
    uint32_t chunkSize_;
    uint32_t maxNumTiles_;
    float invBw_;
    float minVal_;
    uint32_t start_;
    uint32_t end_;
};

template <typename T>
__aicore__ inline void KernelHistc<T>::Init(
    __gm__ T *xGm,
    __gm__ int32_t *outputGm,
    uint32_t numel,
    uint32_t bins,
    uint32_t chunkSize,
    uint32_t maxNumTiles,
    float invBw,
    float minVal)
{
    xGm_.SetGlobalBuffer(xGm);
    outputGm_.SetGlobalBuffer(outputGm);
    numel_ = numel;
    bins_ = bins;
    chunkSize_ = chunkSize;
    maxNumTiles_ = maxNumTiles;
    invBw_ = invBw;
    minVal_ = minVal;

    uint32_t histBytes = bins_ * sizeof(int32_t);
    pipe_.InitBuffer(histBuf_, histBytes);
    uint32_t tileBytes = TILE_SIZE * sizeof(T);
    pipe_.InitBuffer(tileBuf_, tileBytes);
    if constexpr (!std::is_same_v<T, float>) {
        uint32_t castBytes = TILE_SIZE * sizeof(float);
        pipe_.InitBuffer(castBuf_, castBytes);
    }
}

template <typename T>
__aicore__ inline void KernelHistc<T>::Process()
{
    uint32_t cid = AscendC::GetBlockIdx();
    start_ = cid * chunkSize_;
    end_ = start_ + chunkSize_;
    if (end_ > numel_) { end_ = numel_; }

    AscendC::LocalTensor<int32_t> localHist = histBuf_.Get<int32_t>();
    AscendC::LocalTensor<T> tileData = tileBuf_.Get<T>();
    AscendC::LocalTensor<float> tileF32;

    // Zero-initialize histogram
    AscendC::Duplicate(localHist, static_cast<int32_t>(0), bins_);

    if constexpr (!std::is_same_v<T, float>) {
        tileF32 = castBuf_.Get<float>();
    }

    uint32_t tIdx = 0;
    while (tIdx < maxNumTiles_) {
        uint32_t tileStart = start_ + tIdx * TILE_SIZE;
        uint32_t tileLen = end_ - tileStart;
        if (tileLen > TILE_SIZE) { tileLen = TILE_SIZE; }
        if (tileLen == 0) {
            tIdx++;
            continue;
        }

        // CopyIn: GM -> UB via DataCopyPad
        AscendC::DataCopyExtParams copyParams{
            1,
            tileLen * static_cast<uint32_t>(sizeof(T)),
            0, 0, 0
        };
        AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
        AscendC::DataCopyPad(tileData, xGm_[tileStart], copyParams, padParams);
        AscendC::PipeBarrier<PIPE_MTE2>();

        // Prepare float32 tile
        if constexpr (std::is_same_v<T, float>) {
            tileF32 = tileData.template ReinterpretCast<float>();
        } else {
            AscendC::Cast(tileF32, tileData, AscendC::RoundMode::CAST_NONE, tileLen);
            AscendC::PipeBarrier<PIPE_V>();
        }

        // Element-by-element: compute bin index and update histogram
        for (uint32_t i = 0; i < tileLen; i++) {
            float val = tileF32.GetValue(i);
            if (val >= minVal_ && val <= (minVal_ + 1.0f / invBw_)) {
                float xNorm = (val - minVal_) * invBw_;
                int32_t binIdx = static_cast<int32_t>(xNorm);
                if (binIdx < 0) { binIdx = 0; }
                if (binIdx >= static_cast<int32_t>(bins_)) { binIdx = static_cast<int32_t>(bins_) - 1; }
                localHist.SetValue(binIdx, localHist.GetValue(binIdx) + 1);
            }
        }

        tIdx++;
    }

    // CopyOut: write histogram to output at cid * bins
    AscendC::DataCopyExtParams copyOutParams{
        1,
        bins_ * static_cast<uint32_t>(sizeof(int32_t)),
        0, 0, 0
    };
    AscendC::DataCopyPad(outputGm_[cid * bins_], localHist, copyOutParams);
}

